WHERE e1.valid_from <= date('2021-10-03') AND (e1.valid_to IS NULL OR date('2021-10-03') <= e1.valid_to)
  AND NOT EXISTS {
    MATCH (p)-[e2:CONTAINS]->(c)
    WHERE e2.valid_from <= date('2021-11-08') AND (e2.valid_to IS NULL OR date('2021-11-08') <= e2.valid_to)
  }
RETURN c.product_number;
```

