```cypher
MATCH (p:Product)-[:IN_SUBCATEGORY]->(:Subcategory)-[:IN_CATEGORY]->(c:Category {name: 'Bikes'})
WHERE EXISTS {
    MATCH (p)<-[:HAS_LINE]-(o:SalesOrder)-[:IN_TERRITORY]->(t:Territory {name: 'United Kingdom'})
    WHERE date_part('year', o.order_date) = 2023
}
AND NOT EXISTS {
    MATCH (p)<-[:HAS_LINE]-(o:SalesOrder)-[:IN_TERRITORY]->(t:Territory {name: 'Germany'})
    WHERE date_part('year', o.order_date) = 2023
}
RETURN p.product_number AS product_number
ORDER BY product_number
```

